import os
from typing import Any, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _polygon_to_bbox(polygon: Optional[List[float]]) -> Optional[Dict[str, float]]:
    if not polygon:
        return None
    xs = polygon[0::2]
    ys = polygon[1::2]
    if not xs or not ys:
        return None
    return {
        "left": min(xs),
        "top": min(ys),
        "right": max(xs),
        "bottom": max(ys),
        "width": max(xs) - min(xs),
        "height": max(ys) - min(ys),
    }


def _span_text(content: str, spans: Optional[List[Any]]) -> str:
    if not spans:
        return ""
    parts = []
    for span in spans:
        offset = getattr(span, "offset", None)
        length = getattr(span, "length", None)
        if offset is None or length is None:
            continue
        parts.append(content[offset : offset + length])
    return " ".join(p.strip() for p in parts if p and p.strip()).strip()


def _cell_text(result_content: str, cell: Any) -> str:
    text = getattr(cell, "content", None)
    if text and str(text).strip():
        return str(text).strip()
    return _span_text(result_content, getattr(cell, "spans", None))


def _normalize_table(table: Any, table_index: int, result_content: str) -> Dict[str, Any]:
    row_count = getattr(table, "row_count", 0) or 0
    column_count = getattr(table, "column_count", 0) or 0
    cells = getattr(table, "cells", []) or []

    rows: List[Dict[str, Any]] = [
        {
            "row_index": r,
            "cells": [],
        }
        for r in range(row_count)
    ]

    normalized_cells: List[Dict[str, Any]] = []

    for cell in cells:
        row_index = getattr(cell, "row_index", 0) or 0
        column_index = getattr(cell, "column_index", 0) or 0
        row_span = getattr(cell, "row_span", 1) or 1
        column_span = getattr(cell, "column_span", 1) or 1
        kind = getattr(cell, "kind", None)
        bounding_regions = getattr(cell, "bounding_regions", None) or []
        polygon = None
        page_number = None
        if bounding_regions:
            first_region = bounding_regions[0]
            polygon = getattr(first_region, "polygon", None)
            page_number = getattr(first_region, "page_number", None)

        normalized = {
            "table_index": table_index,
            "row_index": row_index,
            "column_index": column_index,
            "row_span": row_span,
            "column_span": column_span,
            "kind": str(kind) if kind is not None else None,
            "text": _cell_text(result_content, cell),
            "page_number": page_number,
            "polygon": polygon,
            "bbox": _polygon_to_bbox(polygon),
        }
        normalized_cells.append(normalized)

        if 0 <= row_index < len(rows):
            rows[row_index]["cells"].append(normalized)

    for row in rows:
        row["cells"].sort(key=lambda c: (c["column_index"], c["row_index"]))
        if row["cells"]:
            bboxes = [c["bbox"] for c in row["cells"] if c["bbox"]]
            if bboxes:
                row["bbox"] = {
                    "left": min(b["left"] for b in bboxes),
                    "top": min(b["top"] for b in bboxes),
                    "right": max(b["right"] for b in bboxes),
                    "bottom": max(b["bottom"] for b in bboxes),
                    "width": max(b["right"] for b in bboxes) - min(b["left"] for b in bboxes),
                    "height": max(b["bottom"] for b in bboxes) - min(b["top"] for b in bboxes),
                }
            else:
                row["bbox"] = None
            row["text"] = " | ".join(c["text"] for c in row["cells"])
        else:
            row["bbox"] = None
            row["text"] = ""

    return {
        "table_index": table_index,
        "row_count": row_count,
        "column_count": column_count,
        "cells": sorted(normalized_cells, key=lambda c: (c["row_index"], c["column_index"])),
        "rows": rows,
    }


def extract_tables_and_rows(
    source: Union[str, bytes],
    *,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
    model_id: str = "prebuilt-layout",
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = api_key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    if isinstance(source, bytes):
        poller = client.begin_analyze_document(
            model_id=model_id,
            body=source,
        )
    elif isinstance(source, str):
        if source.startswith("http://") or source.startswith("https://"):
            poller = client.begin_analyze_document(
                model_id=model_id,
                body={"urlSource": source},
            )
        else:
            with open(source, "rb") as f:
                poller = client.begin_analyze_document(
                    model_id=model_id,
                    body=f.read(),
                )
    else:
        raise TypeError("source must be bytes, a local file path, or a URL")

    result = poller.result()
    content = getattr(result, "content", "") or ""
    tables = getattr(result, "tables", []) or []

    normalized_tables = [
        _normalize_table(table, idx, content)
        for idx, table in enumerate(tables)
    ]

    return {
        "provider": "azure_document_intelligence",
        "model_id": model_id,
        "table_count": len(normalized_tables),
        "tables": normalized_tables,
    }
